    public static void maidBaubleInit(BaubleManager manager) {
        if (ENABLE) {
            MaidRegisterJS.BAUBLE.register(manager);
        }
    }

    public static void maidTaskInit(TaskManager manager) {
        if (ENABLE) {
            MaidRegisterJS.TASK.register(manager);
        }
    }
}

