public class ModKubeJSPlugin
extends KubeJSPlugin {
    public void init() {
        ModKubeJSCompat.ENABLE = true;
        MinecraftForge.EVENT_BUS.register((Object)new CommonEventsPostJS());
        if (ModList.get().isLoaded("jade")) {
            MinecraftForge.EVENT_BUS.register((Object)new JadeEventsPostJS());
        }
        if (ModList.get().isLoaded("theoneprobe")) {
            MinecraftForge.EVENT_BUS.register((Object)new TopEventsPostJS());
        }
    }

    public void onServerReload() {
        if (FMLEnvironment.dist == Dist.CLIENT) {
            MaidTipsOverlay.init();
        }
        BaubleManager.init();
        TaskManager.init();
    }

    public void registerEvents() {
        EventGroup group = MaidEventsJS.GROUP;
        MinecraftForge.EVENT_BUS.post((Event)new RegisterKubeJSEvent(group));
        group.register();
    }

    public void registerRecipeSchemas(RegisterRecipeSchemasEvent event) {
        event.namespace("touhou_little_maid").register(InitRecipes.ALTAR_RECIPE_SERIALIZER.getId().m_135815_(), AltarRecipeSchema.SCHEMA);
    }

    public void registerBindings(BindingsEvent event) {
        event.add("MaidAltarOutput", AltarOutputJS.class);
        event.add("MaidRegister", MaidRegisterJS.class);
        event.add("MaidItemsUtil", ItemsUtil.class);
    }
}

