package com.github.tartaricacid.touhoulittlemaid.compat.kubejs.register.builder;

import com.github.tartaricacid.touhoulittlemaid.api.bauble.IMaidBauble;
import com.github.tartaricacid.touhoulittlemaid.api.task.IRangedAttackTask;
import com.github.tartaricacid.touhoulittlemaid.api.task.meal.MaidMealType;
import com.github.tartaricacid.touhoulittlemaid.entity.passive.EntityMaid;
import com.github.tartaricacid.touhoulittlemaid.item.bauble.BaubleManager;
import com.github.tartaricacid.touhoulittlemaid.util.functional.QuadConsumer;
import com.github.tartaricacid.touhoulittlemaid.util.functional.QuadFunction;
import com.github.tartaricacid.touhoulittlemaid.util.functional.TriConsumer;
import com.github.tartaricacid.touhoulittlemaid.util.functional.TriFunction;
import com.google.common.collect.Maps;
import dev.latvian.mods.kubejs.typings.Info;
import dev.latvian.mods.rhino.util.HideFromJS;
import java.util.Map;
import java.util.function.BiConsumer;
import javax.annotation.Nullable;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import org.apache.commons.lang3.mutable.MutableFloat;

public class MaidBaubleBuilder {
    private final Map<Item, CustomKubeJSBauble> baubles = Maps.newHashMap();

    @Info(value="Bind an item to a maid bauble. And specify a callback function that will be called every tick of the maid. <br>\n將物品與女僕飾品綁定。並且可以指定一個回調函數，在女僕每次 tick 時調用。\n")
    @Deprecated
    public CustomKubeJSBauble bind(Item item, @Nullable BiConsumer<EntityMaid, ItemStack> onTick) {
        CustomKubeJSBauble bauble = new CustomKubeJSBauble();
        bauble.onTick = onTick;
        this.baubles.put(item, bauble);
        return bauble;
    }

    @Info(value="Bind an item to a maid bauble. <br>\n將物品與女僕飾品綁定。\n")
    public CustomKubeJSBauble bind(Item item) {
        CustomKubeJSBauble bauble = new CustomKubeJSBauble();
        this.baubles.put(item, bauble);
        return bauble;
    }

    @HideFromJS
    public void register(BaubleManager manager) {
        this.baubles.forEach(manager::bind);
        this.baubles.clear();
    }

    public static class CustomKubeJSBauble
    implements IMaidBauble {
        @HideFromJS
        @Nullable
        private BiConsumer<EntityMaid, ItemStack> onTick = null;
        @HideFromJS
        @Nullable
        private QuadFunction<EntityMaid, ItemStack, DamageSource, MutableFloat, Boolean> onInjured = null;
        @HideFromJS
        @Nullable
        private TriFunction<EntityMaid, ItemStack, DamageSource, Boolean> onDeath = null;
        @HideFromJS
        @Nullable
        private BiConsumer<EntityMaid, ItemStack> onPutOn = null;
        @HideFromJS
        @Nullable
        private BiConsumer<EntityMaid, ItemStack> onTakeOff = null;
        @HideFromJS
        @Nullable
        private TriConsumer<EntityMaid, ItemStack, Entity> onMeleeAttack = null;
        @HideFromJS
        @Nullable
        private TriConsumer<EntityMaid, ItemStack, IRangedAttackTask> onRangedAttack = null;
        @HideFromJS
        @Nullable
        private QuadConsumer<EntityMaid, ItemStack, ItemStack, MaidMealType> onMaidEat = null;
        @HideFromJS
        @Nullable
        private QuadConsumer<EntityMaid, ItemStack, Integer, Integer> onFavorabilityLevelChange = null;

        @Info(value="When equipped as a bauble, this callback is called every tick. <br>\n當裝備飾品時，每 tick 會調用此回調。\n")
        public CustomKubeJSBauble triggerTick(@Nullable BiConsumer<EntityMaid, ItemStack> c) {
            this.onTick = c;
            return this;
        }

        @Info(value="When the maid is injured while wearing this bauble, this callback is called. <br>\nReturning true indicates that subsequent damage processing is canceled. <br>\n當女僕在佩戴此飾品時受到傷害，會調用此回調。返回 true 表示取消後續傷害處理。\n")
        public CustomKubeJSBauble triggerInjured(@Nullable QuadFunction<EntityMaid, ItemStack, DamageSource, MutableFloat, Boolean> f) {
            this.onInjured = f;
