public class SBackpackCompat {
    private static boolean IS_LOADED = false;

    public static void init() {
        IS_LOADED = true;
        MinecraftForge.EVENT_BUS.register((Object)new BackpackRightClickMaidEvent());
        ExtraContainerManager.register(new SBackpackProvider());
    }

    public static boolean isLoaded() {
        return IS_LOADED;
    }

    public static boolean isBackpack(ItemStack stack) {
        if (SBackpackCompat.isLoaded()) {
            return SBackpackCompatInner.isBackpack(stack);
        }
        return false;
