import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.schedule.Activity;
import net.minecraft.world.level.Level;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.eventbus.api.Event;

public class MaidProvider
implements IProbeInfoEntityProvider {
    private static final String ID = new ResourceLocation("touhou_little_maid", "maid").toString();

    public void addProbeEntityInfo(ProbeMode probeMode, IProbeInfo probeInfo, Player playerEntity, Level world, Entity entity, IProbeHitEntityData iProbeHitEntityData) {
        if (entity instanceof EntityMaid) {
            EntityMaid maid = (EntityMaid)entity;
            if (maid.m_21824_()) {
                IMaidTask task = maid.getTask();
                MutableComponent taskTitle = Component.m_237115_((String)"top.touhou_little_maid.entity_maid.task").m_7220_((Component)task.getName());
                probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)taskTitle);
                MinecraftForge.EVENT_BUS.post((Event)new AddTopInfoEvent(maid, probeMode, probeInfo, iProbeHitEntityData));
                MutableComponent scheduleTitle = Component.m_237115_((String)"top.touhou_little_maid.entity_maid.schedule").m_7220_((Component)this.getActivityTransText(maid));
                probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)scheduleTitle);
                MutableComponent favorabilityTitle = Component.m_237110_((String)"top.touhou_little_maid.entity_maid.favorability", (Object[])new Object[]{maid.getFavorabilityManager().getLevel()});
                probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)favorabilityTitle);
                MutableComponent nextFavorabilityPointTitle = Component.m_237110_((String)"top.touhou_little_maid.entity_maid.nex_favorability_point", (Object[])new Object[]{maid.getFavorabilityManager().nextLevelPoint()});
                probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)nextFavorabilityPointTitle);
            }
            if (maid.getIsInvulnerable()) {
                MutableComponent text = Component.m_237115_((String)"top.touhou_little_maid.entity_maid.invulnerable").m_130940_(ChatFormatting.DARK_PURPLE);
                probeInfo.horizontal(probeInfo.defaultLayoutStyle().alignment(ElementAlignment.ALIGN_CENTER)).text((Component)text);
            }
        }
    }

    public String getID() {
        return ID;
    }

    private MutableComponent getActivityTransText(EntityMaid maid) {
        return this.getActivityTransText(maid.getScheduleDetail());
    }

    private MutableComponent getActivityTransText(Activity activity) {
        return Component.m_237115_((String)("gui.touhou_little_maid.activity." + activity.m_37998_()));
    }
}

